import React from 'react';
import ChartComponent from './ChartComponent';
import Timetable from './Timetable';

export default function LmsDashboard() {
  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>Overview</h1>
      {/* උඩ තියෙන කොටස් 4 */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '20px' }}>
        {['Total Students', 'Total Teachers', 'Active Classes', 'Inactive Students'].map((title, i) => (
          <div key={i} style={{ backgroundColor: '#f0f0f0', padding: '20px', borderRadius: '8px' }}>
            <p>{title}</p> <h2>{1250 - (i * 300)}</h2>
          </div>
        ))}
      </div>

      {/* චාට් එක සහ ස්ටුඩන්ට් ස්ටේටස් එක */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px', marginBottom: '20px' }}>
        <div style={{ backgroundColor: '#f0f0f0', padding: '20px', borderRadius: '8px' }}>
          <h3>Enrollment Growth & Revenue</h3>
          <ChartComponent />
        </div>
        <div style={{ backgroundColor: '#f0f0f0', padding: '20px', borderRadius: '8px' }}>
          <h3>Student Status</h3>
          <p>Ruwan Name</p><p>John Name</p><p>Sama Name</p>
        </div>
      </div>

      {/* යටින් තියෙන ටයිම්ටේබල් එක */}
      <Timetable />
    </div>
  );
}
